actor ControlledLinkClientSource:InboxLinkClientRepository {
    private var pending:CheckedContinuation<InboxLinkClientSource,Never>?,waiter:CheckedContinuation<Void,Never>?
    func source(_ c:InboxConversationFilesContext) async throws -> InboxLinkClientSource {await withCheckedContinuation {pending=$0;waiter?.resume();waiter=nil}}
    func wait() async {if pending==nil {await withCheckedContinuation {waiter=$0}}}
    func resolve(_ s:InboxLinkClientSource) {pending!.resume(returning:s);pending=nil}
}
actor ControlledLinkClientProfiles:ClientSearchRepository {
